const glyphs={'0':['01110','10001','10011','10101','11001','10001','01110'],'1':['00100','01100','00100','00100','00100','00100','01110'],'2':['01110','10001','00001','00010','00100','01000','11111'],'3':['11110','00001','00001','01110','00001','00001','11110'],'4':['00010','00110','01010','10010','11111','00010','00010'],'5':['11111','10000','10000','11110','00001','00001','11110'],'6':['01110','10000','10000','11110','10001','10001','01110'],'7':['11111','00001','00010','00100','01000','01000','01000'],'8':['01110','10001','10001','01110','10001','10001','01110'],'9':['01110','10001','10001','01111','00001','00001','01110'],':':['00000','00100','00100','00000','00100','00100','00000']};
function drawMatrix(el,value){if(el.dataset.value===value)return;el.dataset.value=value;el.replaceChildren();for(const char of value){const g=document.createElement('span');g.className='glyph';for(const row of glyphs[char]||glyphs['0'])for(const bit of row){const dot=document.createElement('i');dot.className='pixel'+(bit==='1'?' on':'');g.append(dot)}el.append(g)}}
const names={'Asia/Dubai':'Abu Dhabi','Asia/Kolkata':'India','America/Los_Angeles':'Los Angeles','America/New_York':'New York'};function city(z){return names[z]||z.split('/').pop().replaceAll('_',' ')}
function renderZones(){const root=$('#clocks');root.replaceChildren();zones.forEach((z,i)=>{const row=document.createElement('div');row.className='clock-row';const matrix=document.createElement('div');matrix.className='matrix';matrix.setAttribute('role','img');matrix.dataset.zone=z;const meta=document.createElement('div');const name=document.createElement('div');name.className='city-name';name.textContent=city(z).toUpperCase();const sub=document.createElement('div');sub.className='city-sub';sub.dataset.zone=z;meta.append(name,sub);const remove=document.createElement('button');remove.className='remove-zone';remove.textContent='×';remove.setAttribute('aria-label',`Remove ${city(z)}`);remove.onclick=()=>{if(zones.length===1)return toast('Keep at least one timezone.');zones.splice(i,1);saveZones();renderZones()};row.append(matrix,meta,remove);root.append(row)});$('#add-zone').disabled=zones.length>=5;$('#add-zone').style.opacity=zones.length>=5?'.4':'1';updateClock()}
