function updateClock(){const now=new Date();document.querySelectorAll('.matrix').forEach(el=>{const z=el.dataset.zone;const parts=new Intl.DateTimeFormat('en-GB',{timeZone:z,hour:'2-digit',minute:'2-digit',hour12:format==='12h',hourCycle:format==='24h'?'h23':undefined}).formatToParts(now);const time=parts.filter(p=>['hour','minute','literal'].includes(p.type)).map(p=>p.value).join('').trim();drawMatrix(el,time);el.setAttribute('aria-label',`${city(z)} ${time}`)});document.querySelectorAll('.city-sub').forEach(el=>{const z=el.dataset.zone;const date=new Intl.DateTimeFormat('en',{timeZone:z,weekday:'short',month:'short',day:'numeric'}).format(now);const daypart=format==='12h'?new Intl.DateTimeFormat('en',{timeZone:z,hour:'numeric',hour12:true}).formatToParts(now).find(p=>p.type==='dayPeriod').value:new Intl.DateTimeFormat('en',{timeZone:z,timeZoneName:'shortOffset'}).formatToParts(now).find(p=>p.type==='timeZoneName').value;el.textContent=`${date} · ${daypart}`});$('#format').textContent=format==='24h'?'24H':'12H';$('#format').setAttribute('aria-label',`Switch to ${format==='24h'?'12':'24'}-hour time`)}
$('#format').onclick=()=>{format=format==='24h'?'12h':'24h';try{localStorage.setItem('quiet-format',format)}catch{}updateClock()};$('#add-zone').onclick=()=>$('#zone-dialog').showModal();$('#zone-form').onsubmit=e=>{e.preventDefault();const z=$('#zone').value;if(zones.includes(z))return toast('That timezone is already on the board.');if(zones.length>=5)return toast('You can add up to five timezones.');zones.push(z);saveZones();renderZones();$('#zone-dialog').close()};
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#zone-dialog').addEventListener('click',e=>{if(e.target===$('#zone-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#year').textContent=new Date().getFullYear();renderZones();setInterval(updateClock,1000);
// A direct pointer on desktop; native text cursors and touch interaction stay intact.
const cursor=$('#cursor');const finePointer=matchMedia('(min-width: 761px) and (hover: hover) and (pointer: fine)');let cursorEnabled=false,lastPointer=null;function hideCursor(){cursor.style.opacity='0';document.body.classList.remove('custom-cursor');cursorEnabled=false}document.addEventListener('pointermove',e=>{lastPointer={x:e.clientX,y:e.clientY};if(!finePointer.matches||e.pointerType==='touch')return;const input=e.target.closest('input,textarea,select,dialog');if(input){hideCursor();return}document.body.classList.add('custom-cursor');cursorEnabled=true;cursor.style.opacity='1';cursor.style.transform=`translate3d(${e.clientX}px,${e.clientY}px,0)`;const target=e.target.closest('a,button');cursor.classList.toggle('is-link',!!target);cursor.querySelector('span').textContent=target?.dataset.cursor||(target?.classList.contains('close')?'CLOSE':target?.classList.contains('remove-zone')?'REMOVE':target?'SELECT':'')},{passive:true});document.documentElement.addEventListener('pointerleave',hideCursor);window.addEventListener('blur',hideCursor);document.addEventListener('keydown',e=>{if(e.key==='Tab')hideCursor()});finePointer.addEventListener('change',hideCursor);document.addEventListener('pointerdown',()=>cursor.classList.add('is-down'));document.addEventListener('pointerup',()=>cursor.classList.remove('is-down'));
