function requestScroll(){if(!scheduled){scheduled=true;requestAnimationFrame(frame)}}window.addEventListener('scroll',requestScroll,{passive:true});window.addEventListener('resize',requestScroll,{passive:true});storyMode.addEventListener('change',syncMode);reducedMotion.addEventListener('change',syncMode);document.querySelectorAll('.project-visual img').forEach(img=>img.addEventListener('load',requestScroll));
function goToScene(i){if(!storyMode.matches){scenes[i].scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth',block:'center'});return}const rect=story.getBoundingClientRect();const range=rect.height-innerHeight+40;window.scrollTo({top:scrollY+rect.top-20+range*(i+.12)/3,behavior:'smooth'})}tabs.forEach((tab,i)=>{tab.onclick=()=>goToScene(i);tab.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();goToScene(next)}}});
document.querySelectorAll('.project-visual').forEach(visual=>{visual.addEventListener('pointermove',e=>{if(reducedMotion.matches||e.pointerType==='touch')return;const rect=visual.getBoundingClientRect();visual.style.setProperty('--rx',`${(e.clientY-rect.top-rect.height/2)/rect.height*-5}deg`);visual.style.setProperty('--ry',`${(e.clientX-rect.left-rect.width/2)/rect.width*5}deg`)});visual.addEventListener('pointerleave',()=>{visual.style.setProperty('--rx','0deg');visual.style.setProperty('--ry','0deg')})});syncMode();
